// The public content pages (rankings/roster/matchup) are readable logged-OUT for
// SEO. Logged-out visitors get "Log in / Sign up" (no "Log out") and a sign-up CTA;
// the same HTML is served to everyone (crawlers included) — no cloaking.
function freeNavLinks(loggedIn, subscribed) {
  if (!loggedIn) return `<a href="/login">Log in</a><a class="pk-upg" href="/signup">Sign up free</a>`;
  return `${subscribed ? `<a href="/">Open app</a>` : `<a class="pk-upg" href="/subscribe">Go Premium</a>`}${subscribed ? `<a href="/account">Account</a>` : `<a href="/api/logout">Log out</a>`}`;
}
const signupBanner = `<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;background:rgba(0,230,104,.08);border:1px solid rgba(0,230,104,.3);border-radius:12px;padding:.8rem 1rem;margin:0 0 1.1rem;color:var(--text)"><span style="font-size:.85rem;line-height:1.4">Create a <strong>free account</strong> to play Pick'em and make your picks, or <a href="/subscribe" style="color:var(--accent);font-weight:700;text-decoration:none">Go Premium</a> for the full fighter database and tools.</span><a href="/signup" style="flex:0 0 auto;background:var(--accent);color:#04120a;font-weight:800;font-size:.8rem;border-radius:8px;padding:.5rem .8rem;white-space:nowrap;text-decoration:none">Sign up free &rarr;</a></div>`;

// Shared sub-nav across every free page so users can always move between the free
// sections (and back to the /matchup home). Styles are scoped inline; the current
// page's tab is highlighted via active. Pass the current path (e.g. "/pickem").
// THE EVENT DAY, IN THE TIMEZONE THE EVENT HAPPENS IN.
//
// card.date is `(ev.startsAt || "").slice(0, 10)` — the first ten characters of a
// UTC timestamp. A UFC card starts Saturday evening in the US, which is already
// SUNDAY in UTC, so that string is a day ahead of the event for every card the site
// covers. The current one: startsAt 2026-07-19T00:00:00Z, prelims
// 2026-07-18T21:00:00Z = Saturday 5:00 PM ET. `date` says 2026-07-19.
//
// Then `new Date(card.date + "T00:00:00")` has no Z, so it parses as LOCAL — which
// in a Cloudflare Worker is UTC — and toLocaleDateString with no timeZone formats in
// UTC too. Two wrongs that agree, which is why it looked deliberate:
//     new Date("2026-07-19T00:00:00").toLocaleDateString(...)  ->  "Sunday, Jul 19"
//
// So: anchor on prelimsAt, the real instant the card starts, and format in
// America/New_York. The fallback re-times a bare date to 18:00Z, which lands on the
// correct US day for any evening card. This is the fix matchupPage already carries;
// it is exported now because FIVE places need it — both reminder emails, the pick'em
// page server-side and client-side, and the matchup page — and five copies of a
// timezone rule is five chances to fix four of them.
// NO card.date FALLBACK, AND THAT IS DELIBERATE. matchupPage's version falls back to
// `card.date + "T18:00:00Z"`, which is 2pm ET ON THE UTC DAY — so it renders the same
// wrong day the bug is about, every time. It is also unreachable: loadUpcomingCard
// sets `date` from `startsAt.slice(0,10)` and `prelimsAt` from
// `prelimsStartsAt || startsAt`, so a date implies a timestamp (checked: 0 of 37
// events in event.json + event-recent.json have one without the other).
//
// A bare calendar day CANNOT be converted to the right ET date — an 8pm ET card and a
// 2pm ET card on the same UTC day need opposite shifts, and the day alone doesn't say
// which. So with no timestamp this returns "" and every caller omits the date, which
// the templates already handle (`${when ? " · " + when : ""}`). On an email that says
// "your picks lock soon", no date beats a wrong one.
export function eventWhen(card, opts) {
  const ts = card && card.prelimsAt;
  if (!ts) return "";
  const d = new Date(ts);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-US", Object.assign(
    { weekday: "long", month: "short", day: "numeric", timeZone: "America/New_York" },
    opts || {}));
}

function freeTabs(active) {
  const row = [["/matchup", "This Week's Card"], ["/rankings", "Rankings"], ["/roster", "Active Roster"]];
  return `
  <style>
    .ftabs{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 .6rem}
    .ftabs a{flex:1 1 auto;text-align:center;min-width:92px;text-decoration:none;font-weight:700;font-size:.82rem;color:var(--text);background:var(--card);border:1px solid var(--border);border-radius:10px;padding:.55rem .7rem;transition:border-color .13s ease,background .13s ease,color .13s ease}
    .ftabs a:hover{border-color:var(--accent);background:var(--surface2)}
    .ftabs a.active{border-color:var(--accent);color:var(--accent);background:var(--surface2)}
    /* The app's "Matchup Analytics Deep Dive" treatment: a green-TINTED panel with a
       green edge, not a slab of #00e668 with near-black text on it. Two of these sit
       side by side under the tabs on four free pages and were the loudest thing on
       each — louder than the rankings they sit above.

       COLOUR ONLY, AND THAT IS A DECISION. .fight-dd-bar is also 'Barlow Condensed',
       uppercase, .14em tracked, and none of that is copied: of the four pages that
       render this strip only /pickem loads Barlow — rankings, roster and matchup have
       no font link at all — so the condensed face would land on one page and a ~35%
       wider fallback on the other three, with the tracking and the uppercase
       magnifying the difference. It would also disagree with the .ftabs tabs directly
       above it, which use the page's own system type. Importing a webfont to restyle
       two buttons is the wrong trade on pages whose whole point is loading fast. */
    .ftab-pick{display:block;text-align:center;text-decoration:none;font-weight:700;font-size:.95rem;letter-spacing:.01em;color:var(--text);background:linear-gradient(180deg,rgba(0,230,104,0.09),rgba(0,230,104,0.03));border:1px solid rgba(0,230,104,0.35);border-radius:8px;padding:.8rem;margin:0;transition:background .15s ease,border-color .15s ease}
    .ftab-pick:hover{background:linear-gradient(180deg,rgba(0,230,104,0.18),rgba(0,230,104,0.07));border-color:var(--accent)}
    /* The two free games share a row and split it. flex:1 1 0 (not 1 1 auto) makes
       them exactly half each regardless of label length — "The Climb →" is shorter
       than "Play Pick'em →" and auto would give Pick'em the bigger half. When one
       is hidden (you're already on that page) the survivor takes the full width on
       its own, which is what the single button did before there were two. */
    .fplay{display:flex;gap:8px;margin:0 0 1.2rem}
    .fplay .ftab-pick{flex:1 1 0;min-width:0}
    @media(max-width:380px){ .fplay .ftab-pick{font-size:.86rem;padding:.8rem .4rem} }
  </style>
  <nav class="ftabs">${row.map(([h, l]) => `<a href="${h}"${h === active ? ' class="active"' : ""}>${l}</a>`).join("")}</nav>
  <div class="fplay">
    ${/* A GUARD, not live behaviour: /theclimb renders climbNav() (a back arrow),
          not these tabs, so today this branch never fires and the Climb button is
          always drawn. Kept so that if the tabs ever come back to that page it
          can't link to itself — but don't read it as evidence they're there. */
      active === "/theclimb" ? "" : `<a class="ftab-pick" href="/theclimb">The Climb →</a>`}
    ${active === "/pickem" ? "" : `<a class="ftab-pick" href="/pickem">Play Pick'em →</a>`}
  </div>`;
}

